import React,{useEffect,useRef,useState} from 'react';import {View,Pressable,ScrollView,StyleSheet,AccessibilityInfo,Linking} from 'react-native';import {CameraView,useCameraPermissions} from 'expo-camera';import {Image} from 'expo-image';import {useQuery} from '@tanstack/react-query';import {useApp,useDraft,useTask} from '../data/AppProvider';import {Screen,Txt,Title,Button,IconButton,Field,NumberField,Toggle,Chips,Segments,Message,Empty,Card,Section,Row,Glass,MacroRow,useNav,CloudNotice,type ScreenProps} from '../ui/components';import {useTheme,layout} from '../ui/theme';import {Icon} from '../ui/Icon';import {choosePhoto,normalizePhoto} from '../native/io';import type {Food,Meal,Recipe,AIJob,AIIngredient,AIRoute,Nutrients} from '../../../../packages/core/types';import {MEALS} from '../../../../packages/core/types';import {entryFromFood,entryFromRecipe,fmt,invariant,normalize,numberInput,recipeNutrition,scaleNutrients,uid,unknownNutrients,validDate} from '../../../../packages/core/utils';import type {RecipeDraft} from './drafts';
export function ScanReview({params}:ScreenProps) {
  const {state,repo}=useApp(),nav=useNav(),task=useTask(),{c}=useTheme();
  const [detailsOpen,setDetailsOpen]=useState(false);
  const job=state.jobs.find(j=>j.id===params.jobId);
  const d=useDraft('scan-review:'+params.jobId,()=>({entryId:uid(),name:'Mi comida',checked:false,meal:'lunch' as Meal,date:state.selectedDate}));
  let nutrients=unknownNutrients(),error='';
  try {invariant(job&&job.ingredients.length,'El análisis todavía no tiene ingredientes.');nutrients=recipeNutrition(scanRecipe(job,state.foods,d.value.name),state.foods)}
  catch(e){error=(e as Error).message}
  return <Screen title="Resultado del escaneo" titleSize={20} tab="home" testID="SC-20" contentStyle={{gap:11}}>
    {job?<>
      {job.mediaUri&&job.route!=='voice'&&<Image source={{uri:job.mediaUri}} contentFit="cover" style={{height:216,borderRadius:26}} accessibilityLabel="Tu foto original de la comida"/>}
      <Glass style={{paddingHorizontal:16,paddingVertical:13,gap:7}}>
        <Txt size={12} tone="secondary">Estimación visual · revisable</Txt>
        {state.profile.showCalories&&<Txt size={32} weight="600">{fmt(nutrients.energy)} kcal</Txt>}
        <MacroRow nutrients={nutrients} showEnergy={false}/>
        <Txt size={11} tone="secondary">Revisá cantidades, aceites y salsas antes de registrar.</Txt>
      </Glass>
      <View style={{gap:7}}>
        <View style={layout.between}><Txt size={15} weight="600">{job.ingredients.length} ingredientes</Txt><Pressable accessibilityRole="button" accessibilityLabel="Añadir ingrediente o salsa" onPress={()=>nav.go('SC-21',{jobId:job.id})} style={{minWidth:44,minHeight:36,alignItems:'center',justifyContent:'center'}}><Icon name="plus" size={20}/></Pressable></View>
        <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{flexGrow:0,flexShrink:0}} contentContainerStyle={{gap:8}}>
          {job.ingredients.map(i=><Pressable key={i.id} accessibilityRole="button" accessibilityLabel={`Corregir ${i.name}, ${fmt(i.amount,1)} ${i.unit}`} onPress={()=>nav.go('SC-21',{jobId:job.id,ingredientId:i.id})} style={{minWidth:92,maxWidth:164,minHeight:48,paddingHorizontal:12,paddingVertical:8,borderRadius:17,borderWidth:StyleSheet.hairlineWidth,borderColor:i.foodId?c.line:c.warning,backgroundColor:c.surface,gap:2}}>
            <Txt size={12} weight="500">{i.name}</Txt><Txt size={11} tone="secondary">{fmt(i.amount,1)} {i.unit}{i.foodId?'':' · elegir fuente'}</Txt>
          </Pressable>)}
        </ScrollView>
      </View>
      <Toggle label="Revisé cantidades, aceites y salsas" value={d.value.checked} onChange={checked=>d.set({checked})}/>
      <Button testID="scan-register" title={job.state==='applied'?'Comida ya registrada':'Registrar comida'} icon="plus" disabled={!!error||!d.value.checked||job.state==='applied'} busy={task.busy} onPress={()=>task.run(async()=>{
        await d.flush();
        const r=scanRecipe(job,state.foods,d.value.name);
        const entry=entryFromRecipe(r,state.foods,1,d.value.date,d.value.meal,state.profile.timezone);entry.id=d.value.entryId;
        await repo.dispatchMany([{type:'entry',entry},{type:'job',job:{...job,state:'applied'}},{type:'dropDraft',key:d.key}],'confirm-scan:'+job.id);
        nav.completeRegistration();
      })}/>
      <View style={layout.between}><Button title={`${MEALS[d.value.meal]} · editar`} variant="quiet" onPress={()=>setDetailsOpen(!detailsOpen)}/><Button title="Escanear otra" variant="quiet" onPress={()=>nav.go('SC-18')}/></View>
      {detailsOpen&&<View style={{gap:12}}><Field label="Nombre de la comida" value={d.value.name} onChangeText={name=>d.set({name})}/><Chips options={mealOptions} value={d.value.meal} onChange={meal=>d.set({meal})}/><Txt tone="secondary" size={12}>Fecha del registro: {d.value.date}</Txt><Txt size={12} tone="secondary">Una foto no permite conocer todos los ingredientes ni sus cantidades exactas. Los nutrientes se recalculan al corregir las fuentes.</Txt></View>}
    </>:<Empty title="Análisis no encontrado" detail="Abrí un trabajo reciente o tomá una nueva foto."/>}
    <Message type="error">{task.error||d.error||error}</Message>
  </Screen>;
}
